### Python代码

```python
def check(c):
    # 判断字符类型
    if c.islower():
        return 1
    elif c.isupper():
        return 2
    elif c.isdigit():
        return 3
    return 0

def solve(n, s, t):
    result = []
    for i in range(n):
        if check(s[i]) > 0 and check(t[i]) > 0:
            # 获取字符的ASCII值
            a = ord(s[i])
            b = ord(t[i])
            # 确保a <= b
            if a > b:
                a, b = b, a
            # 如果等级相同，输出字符，否则输出ASCII码
            if check(s[i]) == check(t[i]):
                mid_char = chr((a + b + 1) // 2)
                result.append(mid_char)
            else:
                mid_ascii = (a + b + 1) // 2
                result.append(str(mid_ascii))
        else:
            result.append('_')
    return ''.join(result)

# 输入
n = int(input())
s = input()
t = input()

# 输出结果
print(solve(n, s, t))
```

